/** The app's confirmation dialog: waits for it, presses its action (`yes`) or Renunță, and returns its question. */
export async function answer(yes = true): Promise<string> {
  const dialog = await waitFor(() => {
    const d = document.querySelector<HTMLElement>(".ask[role=dialog]");
    expect(d).not.toBeNull();
    return d!;
  });
  fireEvent.click(dialog.querySelectorAll("button")[yes ? 0 : 1]);
  return dialog.getAttribute("aria-label") ?? "";
}

/** "Cum ai plătit?" (MarkPaid): picks `how` (a method's title) and presses Marchează ca plătită. Returns the dialog. */
export async function markPaidAs(how: string): Promise<HTMLElement> {
  const dialog = await screen.findByRole("dialog", { name: "Cum ai plătit?" });
  await userEvent.click(within(dialog).getByRole("radio", { name: new RegExp(`^${how}`) }));
  await userEvent.click(within(dialog).getByRole("button", { name: "Marchează ca plătită" }));
  return dialog;
}

export const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });

export function deferred<T>() {
  let resolve!: (v: T) => void;
  const promise = new Promise<T>((ok) => (resolve = ok));
  return { promise, resolve };
}

export type Call = { url: string; method: string; body: Record<string, unknown> | undefined; raw?: BodyInit; type?: string };

