/** Exercise the engine's pure collectors when a test changes its complete fixture. */
function engineData(view: View, query: Record<string, string | undefined>, kind: "tasks" | "search" | "browse" | "dashboard_rows" | "shell" | "metadata" | "detail" | "partner" | "choices", prepared?: Payment[]): string {
  const root = fileURLToPath(new NodeURL("../../", import.meta.url));
  const script = `import json,runpy,sys
v,q,kind,prepared=json.load(sys.stdin)
if kind=="choices" or (kind=="detail" and q.get("kind")=="transaction"):
 from fiscalm.api import transaction_choices
 ids={p["item_id"]:f"fixture-payment-{s['co']}-{i}" for s in v.get("parts",[v]) for i,p in enumerate(prepared[s["co"]])}
 # Pure projection tests never read or create an install's payment-ID secret.
 transaction_choices.api.payment_id=ids.__getitem__
 for s in v.get("parts",[v]): s["prepared_payments"]={"held":prepared[s["co"]],"in_file":[],"lost":[],"imported":[]}
 if kind=="choices":
  q.pop("co",None)
  s=next((s for s in v.get("parts",[v]) if any(t["id"]==q["id"] for t in s["transactions"]["rows"])),None)
  print(json.dumps(transaction_choices.project(s,q)) if s else "null");sys.exit()
if kind=="partner":
 from fiscalm.api import partner_rows
 from fiscalm.api.lists import metadata
 q.pop("co",None)
 s=next((s for s in v.get("parts",[v]) if not q.get("id") or any(p["id"]==q["id"] for p in s["partners"])),None)
 print(json.dumps(partner_rows.project(s,metadata(s),q)) if s else "null");sys.exit()
if kind=="detail":
 from fiscalm.api import details
 from fiscalm.api.lists import metadata
 q.pop("co",None)
 k,identity,offset,limit=details.options(q)
 for s in v.get("parts",[v]):
  row=details.find(s,k,identity)
  if row is not None:
   print(json.dumps(details.context(s,metadata(s),k,row,offset,limit)));sys.exit()
 print("null");sys.exit()
if kind in ("shell","metadata"):
 from fiscalm.api.tasks import Collector
 c=Collector()
 for s in v.get("parts",[v]):
  own=Collector();own.add(s);s["task_summary"]=own.result()
  if "parts" in v: c.add(s)
 if "parts" in v: v["task_summary"]=c.result()
 if kind=="metadata":
  from fiscalm.api.lists import metadata
  context={k:q[k] for k in ("client_id","issued_id") if q.get(k)}
  v=({**v,"parts":[metadata(s) for s in v["parts"]],"dashboard":{**v["dashboard"],"upcoming":[]},"bounded":True,"upcoming_count":sum(len(s["dashboard"]["upcoming"]) for s in v["parts"])} if "parts" in v else metadata(v,**context))
 print(json.dumps(v));sys.exit()
if kind=="dashboard_rows":
 from fiscalm.api.dashboard_rows import project
 parts={s["co"]:s for s in v.get("parts",[v])}
 print(json.dumps(project(list(parts),parts.__getitem__,q)))
 sys.exit()
Collector=runpy.run_path("src/fiscalm/api/"+kind+".py")["Collector"]
c=Collector(q.get("q", "")) if kind=="search" else Collector(q) if kind=="browse" else Collector(int(q.get("cursor") or 0),50,q.get("group", ""))
for s in v.get("parts",[v]): c.add(s)
print(json.dumps(c.result()))`;
  return execFileSync(`${root}.venv/bin/python`, ["-c", script], { cwd: root, input: JSON.stringify([view, query, kind, Object.fromEntries(("parts" in view ? view.parts : [view]).map((s) => [s.co, prepared ?? fixturePreparedPayments(s.co)]))]), encoding: "utf8" });
}

const engineResponse = (...args: Parameters<typeof engineData>) => json(JSON.parse(engineData(...args)));

export const browseResult = (view: View, screen: BrowseScreen, query: Record<string, string | undefined> = {}) => JSON.parse(engineData(view, { screen, ...query }, "browse"));

export const summaryResult = <T extends View>(state: T, navigation: Record<string, string> = {}): T => JSON.parse(engineData(state, navigation, "metadata"));
export const detailResult = (view: View, query: Record<string, string | undefined>, prepared?: Payment[]) => JSON.parse(engineData(view, query, "detail", prepared));
export const choicesResult = (view: View, query: Record<string, string | undefined>, prepared?: Payment[]) => JSON.parse(engineData(view, query, "choices", prepared));
export const partnerResult = (view: View, query: Record<string, string | undefined>) => JSON.parse(engineData(view, query, "partner"));

/** Full fake replies rebuild the engine shell after mutations; bounded replies already carry authoritative scalars. */
function compileShell(view: View): View {
  if (!("dashboard" in view)) return view;
  fixtureDashboardPages(view);
  return "bounded" in view && view.bounded ? view : JSON.parse(engineData(view, {}, "shell")) as View;
}

export const dashboardResult = (view: View, collection: DashboardCollection, cursor = "") => JSON.parse(engineData(view, { collection, cursor }, "dashboard_rows"));

export function searchResult(view: View, query: string): SearchResults {
  return JSON.parse(engineData(view, { q: query }, "search")) as SearchResults;
}

/** Stubs fetch. `state` answers each GET of a company's state (ALL answers from the fixture unless `all` is given);
 * `onPost` each POST. Like the engine, GET api/invoicing answers what the last POST said invoicing now holds (the app
 * reads it again after every action), unless the test gives its own `invoicing`. */
export function server({ identity = () => json(renderedIdentity ?? fixtureIdentity()), state = (url: string) => json(fixture(new URL(url, "http://local").searchParams.get("co") === "STUDIO9" ? "STUDIO9" : "NORD")), all = () => json(fixtureAll()), onPost = () => json({ ok: true, message: "", state: fixture() }),
  cliStatus = () => json({ provider: "", state: "idle", url: "", code: "", needs_code: false, readiness: "not_logged_in", install_command: "docker compose up -d --build" }),
  backup = () => json({ last_backup: null }), integrations = () => json(fixtureIntegrations()), invoicing, search, browse, reportPages, dashboardPage, detail, transactionChoices, partnerPages, uploadLinks = () => json([]),
  users = () => json([]), userSessions = () => json([]), products = () => json([]), tokens = () => json([]), historyReview = () => json({ rows: [] }), paymentFile, companies = () => json({ companies: [], palettes: [], limits: { key_pattern: "", reserved_keys: [], name_max: 100 } }) }: {
  identity?: () => Response | Promise<Response>;
  reportPages?: (url: string) => Response | Promise<Response>;
  detail?: (url: string) => Response | Promise<Response>;
  transactionChoices?: (url: string) => Response | Promise<Response>;
  partnerPages?: (url: string) => Response | Promise<Response>;
  dashboardPage?: (url: string) => Response | Promise<Response>;
  browse?: (url: string) => Response | Promise<Response>;
  search?: (url: string) => Response | Promise<Response>;
  state?: (url: string) => Response | Promise<Response>;
  all?: () => Response | Promise<Response>;
  backup?: () => Response | Promise<Response>;
  integrations?: () => Response | Promise<Response>;
  cliStatus?: () => Response | Promise<Response>;
  invoicing?: (url: string) => Response | Promise<Response>;
  uploadLinks?: (url: string) => Response | Promise<Response>;
  users?: () => Response | Promise<Response>;
  products?: (url: string) => Response | Promise<Response>;
  userSessions?: (url: string) => Response | Promise<Response>;
  tokens?: () => Response | Promise<Response>;
  historyReview?: () => Response | Promise<Response>;
  companies?: () => Response | Promise<Response>;
  paymentFile?: (url: string) => Response | Promise<Response>;
  onPost?: (c: Call) => Response | Promise<Response>;
} = {}) {
  const calls: Call[] = [];
  let written: Invoicing | undefined;
  const states: Record<string, View> = {};
  const answerPost = async (c: Call) => {
    const r = await onPost(c);
    const body: unknown = await r.clone().json().catch(() => null);
    if (body && typeof body === "object" && "invoicing" in body && body.invoicing) written = body.invoicing as Invoicing;
    if (body && typeof body === "object" && "state" in body && body.state && typeof body.state === "object") {
      const state = compileShell(body.state as View);
      const id = "id" in body && typeof body.id === "string" && "ok" in body && body.ok ? body.id : "";
      const navigation: Record<string, string> = id && c.url.endsWith("/client-save") ? { client_id: id }
        : id && /\/(issue|storno)$/.test(c.url) ? { issued_id: id } : {};
      body.state = state.bounded || !("dashboard" in state) ? state : summaryResult(state, navigation);
      // A compact wire reply cannot replace the complete model behind subsequent paged reads.
      if (!state.bounded || !states[state.co]) states[state.co] = state;
      return new Response(JSON.stringify(body), { status: r.status, headers: r.headers });
    }
    return r;
  };
  const respond = async (url: string, init: RequestInit = {}) => {
    // A JSON body is read back; anything else (an image upload) is kept as it was sent, in `raw`.
    const isJson = typeof init.body === "string";
    const c: Call = { url, method: init.method ?? "GET", body: isJson ? JSON.parse(String(init.body)) : undefined };
    if (init.body && !isJson) Object.assign(c, { raw: init.body, type: new Headers(init.headers).get("Content-Type") ?? undefined });
    calls.push(c);
    if (c.method === "POST") return answerPost(c);
    if (url.endsWith("api/me")) return identity();
    if (url.includes("api/bootstrap?")) {
      const who = await identity();
      if (!who.ok) return who;
      const co = new URL(url, "http://local").searchParams.get("co") ?? "ALL";
      const r = await (co === "ALL" ? all() : state(url));
      if (!r.ok) return r;
      const v = compileShell(await r.clone().json() as View);
      states[co] = v;
      return json({ identity: await who.clone().json(), state: !("bounded" in v && v.bounded) && "dashboard" in v ? summaryResult(v) : v, live: false });
    }
    if (url.includes("api/backup")) return backup();
    if (url.includes("api/integrations")) return integrations();
    if (url.includes("api/integration-cli")) return cliStatus();
    if (url.includes("api/invoicing?")) return invoicing ? invoicing(url) : json(written ?? invoicingData());
    if (url.includes("api/upload-links?")) return uploadLinks(url);
    if (url.includes("api/products?")) return products(url);
    if (url.includes("api/tokens")) return tokens();
    if (url.endsWith("api/users")) return users();
    if (url.includes("api/user-sessions?")) return userSessions(url);
    if (url.includes("api/history-review")) return historyReview();
    if (url.includes("api/companies")) return companies();
    if (url.includes("api/payment-files/")) {
      if (paymentFile) return paymentFile(url);
      const f = (paymentFiles as Record<string, unknown>)[url.split("/").pop()!];
      return f ? json(f) : json({ ok: false, message: "not found" }, 404);
    }
    const query = new URL(url, "http://local").searchParams;
    const co = query.get("co") ?? "NORD";
    if (url.includes("api/transaction-choices")) {
      if (transactionChoices) return transactionChoices(url);
      const combined = states.ALL;
      const source = states[co] ?? (combined && "parts" in combined ? combined.parts.find((s) => s.co === co) : undefined)
        ?? (co === "ALL" ? fixtureAll() : fixture(co === "STUDIO9" ? "STUDIO9" : "NORD"));
      const result = choicesResult(source, Object.fromEntries(query));
      return json(result, result ? 200 : 404);
    }
    if (url.includes("api/partner-pages")) {
      if (partnerPages) return partnerPages(url);
      const combined = states.ALL;
      const source = states[co] ?? (combined && "parts" in combined ? combined.parts.find((s) => s.co === co) : undefined)
        ?? (co === "ALL" ? fixtureAll() : fixture(co === "STUDIO9" ? "STUDIO9" : "NORD"));
      const result = partnerResult(source, Object.fromEntries(query));
      return json(result, result ? 200 : 404);
    }
    if (url.includes("api/detail")) {
      if (detail) return detail(url);
      const result = detailResult(states[co] ?? (co === "ALL" ? fixtureAll() : fixture()), Object.fromEntries(query));
      return json(result, result ? 200 : 404);
    }
    if (url.includes("api/dashboard-list")) return dashboardPage ? dashboardPage(url) : json(fixtureDashboardData(states[co] ?? (co === "ALL" ? fixtureAll() : fixture()), query.get("collection") as DashboardCollection, query.get("cursor") ?? ""));
    if (url.includes("api/report-pages")) return reportPages ? reportPages(url) : json(fixtureReportPagesData(states[co] ?? (co === "ALL" ? fixtureAll() : fixture()), query.get("month")!));
    if (url.includes("api/browse")) return browse ? browse(url) : json(fixtureBrowseData(states[co] ?? (co === "ALL" ? fixtureAll() : fixture()), query.get("screen") as BrowseScreen, Object.fromEntries(query)));
    if (url.includes("api/tasks")) return engineResponse(states[co] ?? (co === "ALL" ? fixtureAll() : fixture()), Object.fromEntries(query), "tasks");
    if (url.includes("api/search")) return search ? search(url) : engineResponse(states[co] ?? (co === "ALL" ? fixtureAll() : fixture()), Object.fromEntries(query), "search");
    if (url.includes("api/state-list")) {
      const full = states[co] as State;
      const rows = (full.ambiguous.find((r) => r.tx === query.get("tx"))?.candidates ?? []).map((r, i) => ({ ...r, cursor_id: String(i).padStart(9, "0") }));
      const sorted = rows.slice().filter((r) => r.cursor_id > (query.get("cursor") ?? ""));
      return json({ data: sorted.slice(0, 50), total: rows.length, next_cursor: sorted.length > 50 ? sorted[49].cursor_id : null });
    }
    return json({ ok: false, message: "not found" }, 404);
  };
  // As a browser's: an aborted request (the app's own, or its deadline) rejects, even while its answer never comes.
  const fetch = vi.fn((url: string, init: RequestInit = {}) => new Promise<Response>((resolve, reject) => {
    const abort = () => reject(new DOMException("The operation was aborted.", "AbortError"));
    if (init.signal?.aborted) return abort();
    init.signal?.addEventListener("abort", abort, { once: true });
    respond(url, init).then(resolve, reject);
  }));
  vi.stubGlobal("fetch", fetch);
  return {
    calls,
    posts: () => calls.filter((c) => c.method === "POST"),
    gets: (co = "") => calls.filter((c) => c.method === "GET" && c.url.includes(`api/bootstrap?co=${co}`)),
  };
}

export function at(query: string) {
  window.history.replaceState(null, "", `/web/${query}`);
}

/** The De achitat card's total as text ("8.052,30"). */
export const payable = () => document.querySelector(".money .amt")?.textContent?.replace("lei", "").trim();

export const acts = () => screen.getByText("Pregătește plățile", { exact: true }).closest("div") as HTMLElement;

/** An explicit synthetic principal for private-component tests; public/auth tests keep native render. */
export function renderSignedIn(ui: ReactNode, options: RenderOptions & { identity?: Identity } = {}) {
  const { identity = fixtureIdentity(), wrapper: Wrapper, ...rest } = options;
  renderedIdentity = identity;
  return render(ui, { ...rest, wrapper: ({ children }) => createElement(IdentityContext.Provider,
    { value: { identity, signOut: async () => {}, refreshIdentity: async () => {} } }, Wrapper ? createElement(Wrapper, null, children) : children) });
}

/** Mount the real app against the shared fake engine; navigation stays explicit in each test. */
export function renderApp(options: Parameters<typeof server>[0] & { principal?: Identity; strict?: boolean } = {}) {
  const { principal, strict, ...responses } = options;
  const api = server(responses);
  renderSignedIn(createElement(App), { identity: principal, reactStrictMode: strict });
  return api;
}

/** Change only the partner relevant to a scenario. */
export function withPartner(id: string, change: Partial<Partner>): State {
  const s = fixture();
  s.partners = s.partners.map((p) => p.id === id ? { ...p, ...change } : p);
  return s;
}

/** Toate firmele with one company's part replaced. */
export function allWith(part: State): AllState {
  const a = fixtureAll();
  a.parts = a.parts.map((p) => p.co === part.co ? part : p);
  return a;
}

/** The visible detail rows of a sheet, including unlabelled warnings. */
export function facts(d: HTMLElement): string[] {
  const list = d.querySelector("details dl")!;
  return [...Array.from(list.querySelectorAll("dt"), term => `${term.textContent}: ${term.nextElementSibling?.textContent}`),
    ...Array.from(list.parentElement!.querySelectorAll(":scope > p"), note => note.textContent ?? "")];
}

