/** Refresh the app through the same browser event as returning to its tab. */
export function becomeVisible() {
  Object.defineProperty(document, "visibilityState", { value: "visible", configurable: true });
  document.dispatchEvent(new Event("visibilitychange"));
}

/** State with no urgent tasks; callers keep only the reminders they exercise. */
export function taskState(patch: Partial<State> = {}): State {
  const s = fixture();
  Object.assign(s, { ambiguous: [], refused: [], to_check: [], unreadable: [], reports: [] });
  s.files = [];
  s.invoices = s.invoices.map((r) => ({ ...r, due_date: "2026-12-31" }));
  s.system = { ...s.system, anaf: { ...s.system.anaf, authorized: true, days_left: 200, error: null },
    mail: { ...s.system.mail, stale: false } };
  return { ...s, ...patch };
}

/** A list response, including an empty result, has finished replacing the previous page. */
export const listLoaded = () => waitFor(() => expect(document.querySelector("main .card[aria-busy]"))
  .toHaveAttribute("aria-busy", "false"));

/** Picks a choice in the app's `Select` (Controls.tsx) as a person does: opens its list, then clicks the option whose value
 * or text is `choice` (as userEvent.selectOptions takes either). */
export async function choose(combobox: HTMLElement, choice: string) {
  if (combobox.getAttribute("aria-expanded") !== "true") await userEvent.click(combobox);
  const list = document.getElementById(combobox.getAttribute("aria-controls") ?? "");
  const option = [...(list?.querySelectorAll<HTMLElement>("[role=option]") ?? [])]
    .find((o) => o.dataset.value === choice || o.textContent === choice);
  if (!option) throw new Error(`No choice "${choice}" in ${combobox.id || combobox.getAttribute("aria-label")}`);
  await userEvent.click(option);
}

/** The choices a `Select` offers, value and text, read from its open list (opened if it is closed, then closed again, without moving focus). */
export async function choicesOf(combobox: HTMLElement): Promise<{ value: string; text: string }[]> {
  const wasOpen = combobox.getAttribute("aria-expanded") === "true", focused = document.activeElement as HTMLElement | null;
  if (!wasOpen) fireEvent.click(combobox);
  const list = document.getElementById(combobox.getAttribute("aria-controls") ?? "");
  const out = [...(list?.querySelectorAll<HTMLElement>("[role=option]") ?? [])].map((o) => ({ value: o.dataset.value ?? "", text: o.textContent ?? "" }));
  if (!wasOpen) fireEvent.click(combobox);
  focused?.focus(); // reading leaves focus where it was
  return out;
}
